import{_ as e,o as s,c as t,a2 as n}from"./chunks/framework.D7WGirly.js";const u=JSON.parse('{"title":"数据处理脚本","description":"","frontmatter":{"title":"数据处理脚本","order":15},"headers":[],"relativePath":"development/scripts.md","filePath":"development/scripts.md"}'),i={name:"development/scripts.md"};function l(o,a,p,r,c,d){return s(),t("div",null,[...a[0]||(a[0]=[n(`<h1 id="数据处理脚本" tabindex="-1">数据处理脚本 <a class="header-anchor" href="#数据处理脚本" aria-label="Permalink to &quot;数据处理脚本&quot;">​</a></h1><h2 id="统计数据集序列信息" tabindex="-1">统计数据集序列信息 <a class="header-anchor" href="#统计数据集序列信息" aria-label="Permalink to &quot;统计数据集序列信息&quot;">​</a></h2><h3 id="介绍" tabindex="-1">介绍： <a class="header-anchor" href="#介绍" aria-label="Permalink to &quot;介绍：&quot;">​</a></h3><ul><li>计算数据集中序列的信息（序列长度的最大值｜最小值｜总和｜平均值，序列条数，序列之间的相似度）</li><li>作出序列长度分布图和序列相似度分布图</li></ul><h3 id="用法" tabindex="-1">用法： <a class="header-anchor" href="#用法" aria-label="Permalink to &quot;用法：&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python dataInfo.py input.fasta mafft datasetName</span></span></code></pre></div><p>参数描述：</p><ul><li><code>input.fasta</code>：待计算相似度的数据集，必须为<strong>fasta格式</strong></li><li><code>mafft</code>：mafft路径，用于两两序列比对</li><li><code>datasetName</code>：数据集名称，用于命名序列信息文件</li><li>datasetName.txt 序列基本信息（序列条数和长度）</li><li>datasetName_Distri.png 序列长度分布图</li><li>similarity_datasetName.txt 两两序列相比的相似度值</li><li>similarity_datasetName.png 序列相似度分布图</li></ul><p><a href="https://github.com/malabz/JMSA" target="_blank" rel="noreferrer">源代码</a></p><h2 id="处理非法字符的脚本" tabindex="-1">处理非法字符的脚本 <a class="header-anchor" href="#处理非法字符的脚本" aria-label="Permalink to &quot;处理非法字符的脚本&quot;">​</a></h2><h3 id="介绍-1" tabindex="-1">介绍： <a class="header-anchor" href="#介绍-1" aria-label="Permalink to &quot;介绍：&quot;">​</a></h3><ul><li>用于处理多序列比对后的fasta文件</li><li>该脚本将RNA序列文件中的碱基“U”替换为“T”，并将非法字符（如“:”）替换为“N”</li><li>处理后的文件存储在 resultName_processed.fasta</li></ul><h3 id="用法-1" tabindex="-1">用法： <a class="header-anchor" href="#用法-1" aria-label="Permalink to &quot;用法：&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>python preprocess.py filepath resultName</span></span></code></pre></div><p>参数描述：</p><ul><li><code>filepath</code>：要处理的fasta文件的路径</li><li><code>resultName</code>：处理后的Fasta文件名</li></ul><p><a href="https://github.com/malabz/MSATOOLS/tree/main/preprocess" target="_blank" rel="noreferrer">源代码</a></p><h2 id="处理n的脚本" tabindex="-1">处理N的脚本 <a class="header-anchor" href="#处理n的脚本" aria-label="Permalink to &quot;处理N的脚本&quot;">​</a></h2><h3 id="介绍-2" tabindex="-1">介绍： <a class="header-anchor" href="#介绍-2" aria-label="Permalink to &quot;介绍：&quot;">​</a></h3><p>在比对核苷酸的序列时，N的存在影响比对的难度。同时，不同的比对软件对于N的处理各不相同，得到的比对结果有的包含N，有的将N删掉了，难以比较软件的精度。该脚本处理数据后，可以降低比对的难度并统一比对后的结果，方便比较软件优劣。</p><ul><li>比对前删除N</li><li>比对后插回N</li></ul><h3 id="用法-2" tabindex="-1">用法： <a class="header-anchor" href="#用法-2" aria-label="Permalink to &quot;用法：&quot;">​</a></h3><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span># 使用前先编译</span></span>
<span class="line"><span>g++ deal_N.cpp -o xxx</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 以下内容是Unix系统的使用方法，在Windows系统下使用时仅将./xxx替换为xxx.exe即可</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 1 删除文件中的N并记录N的位置</span></span>
<span class="line"><span>./xxx -1 in_original.fasta out_removeN.fasta recordN.tmp</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 2 将N插入到比对结果中</span></span>
<span class="line"><span>./xxx -2 in_ans_withoutN.fasta out_ans_withN.fasta recordN.tmp</span></span>
<span class="line"><span></span></span>
<span class="line"><span># 3 从源文件和结果文件中生成带有N的最终结果文件</span></span>
<span class="line"><span>./xxx -3 in_original.fasta in_ans_withoutN.fasta out_ans_withN.fasta</span></span></code></pre></div><p>参数描述：</p><ul><li><code>-1｜-2｜-3</code>：选择的功能号</li><li><code>in_original.fasta</code>：带N的比对前的数据</li><li><code>out_removeN.fasta</code>：删掉N的比对前的数据</li><li><code>recordN.tmp</code>：记录N的位置信息文件</li><li><code>in_ans_withoutN.fasta</code>：没有N的比对结果</li><li><code>out_ans_withN.fasta</code>：将N插回原位的比对结果</li></ul><p><a href="https://github.com/malabz/MSATOOLS/tree/main/deal_N_tool" target="_blank" rel="noreferrer">源代码</a></p>`,26)])])}const m=e(i,[["render",l]]);export{u as __pageData,m as default};
